  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Lamotrigine, which is the query molecule (3,5-diamino-6-(2,3-dichlorophenyl)-1,2,4-triazine), has an absolute oral bioavailability of 98% in humans, directly demonstrating high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Pyrimethamine, a structurally related 2,4-diaminopyrimidine with a chlorophenyl substituent, is well absorbed orally with bioavailability >90% in healthy adults, supporting high bioavailability for the diaminopyrimidine/triazine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Clonidine, a small dichlorophenyl heteroaromatic drug, shows high oral bioavailability (75–95%) in humans, supporting that the dichlorophenyl-triazine scaffold is not inherently poorly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Felodipine has low oral bioavailability (~15%) in healthy subjects due to extensive CYP3A4 first-pass metabolism, but its ester-containing dihydropyridine scaffold is not transferable to the diaminotriazine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is lamotrigine, with direct human evidence of 98% absolute oral bioavailability. Multiple structurally related diaminopyrimidine/triazine and dichlorophenyl heteroaromatic drugs (pyrimethamine, clonidine, guanfacine, brotizolam, etizolam) also show high oral bioavailability. The low-bioavailability analogues (felodipine, azosemide) are structurally dissimilar and their low F is driven by metabolic liabilities not present in the query.",
